// A Verus program that, given two non-empty arrays of f32, constructs
// a broadcast grid representing their Cartesian product.
// It ensures the returned structure's shape matches the input sizes,
// and the element accessor returns pairs as specified.

verus! {

struct BroadcastObject {
    // The shape of the broadcast grid: length of first array, length of second array.
    shape: (usize, usize),
    // Store the input arrays internally.
    x: Vec<f32>,
    y: Vec<f32>,
}

impl BroadcastObject {
    /// Returns the length of the first dimension.
    spec fn dim0(&self) -> nat {
        self.shape.0
    }
    /// Returns the length of the second dimension.
    spec fn dim1(&self) -> nat {
        self.shape.1
    }
    /// The logical contents of the broadcast grid as a function mapping indices to pairs.
    spec fn element(&self, i: nat, j: nat) -> (f32, f32)
        recommends i < self.dim0() && j < self.dim1()
    {
        requires i < self.dim0() && j < self.dim1();
        (self.x[i], self.y[j])
    }
}

fn broadcast(x: Vec<f32>, y: Vec<f32>) -> BroadcastObject
    requires x.len() > 0
    requires y.len() > 0
    ensures |result: BroadcastObject| {
        // The shape matches the lengths of the input arrays.
        result.shape.0 == x.len() &&
        result.shape.1 == y.len() &&
        // For all valid indices, the element matches the Cartesian product.
        forall |i: usize, j: usize| (i < x.len() && j < y.len()) ==>
            result.element(i, j) == (x[i], y[j])
    }
{
    BroadcastObject {
        shape: (x.len(), y.len()),
        x,
        y,
    }
}

}